export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceLines: (callback: (payload: Lines) => void) => listen<Lines>("appearance.lines", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	library: string,
	launchPaths: string[],
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	lines: Lines,
	locale: Locale,
};

export type Corners = "rounded" | "square";

export type Entry = {
	folder: string,
	meta: Value,
};

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Kind = "pdf" | "image" | "importable";

export type Library = {
	root: string,
	subjects: Subject[],
};

export type Lines = "none" | "lines" | "scanlines";

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Subject = {
	notebooks: Entry[],
} & Entry;

export type Trashed = {
	id: string,
	from: string,
	trashedAt: number,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };
